class Solution {
public:
    int digArtifacts(int n, vector<vector<int>>& artifacts, vector<vector<int>>& dig) {
        vector<vector<bool>> dug(n, vector<bool>(n, false));
        for (const auto& d : dig) {
            dug[d[0]][d[1]] = true;
        }
        int ans = 0;
        for (const auto& a : artifacts) {
            bool ok = true;
            for (int r = a[0]; r <= a[2] && ok; r++) {
                for (int c = a[1]; c <= a[3] && ok; c++) {
                    if (!dug[r][c]) ok = false;
                }
            }
            if (ok) ans++;
        }
        return ans;
    }
};

class Solution {
    public int digArtifacts(int n, int[][] artifacts, int[][] dig) {
        boolean[][] dug = new boolean[n][n];
        for (int[] d : dig) {
            dug[d[0]][d[1]] = true;
        }
        int ans = 0;
        for (int[] a : artifacts) {
            boolean ok = true;
            for (int r = a[0]; r <= a[2] && ok; r++) {
                for (int c = a[1]; c <= a[3] && ok; c++) {
                    if (!dug[r][c]) ok = false;
                }
            }
            if (ok) ans++;
        }
        return ans;
    }
}

/**
 * @param {number} n
 * @param {number[][]} artifacts
 * @param {number[][]} dig
 * @return {number}
 */
var digArtifacts = function(n, artifacts, dig) {
    const dug = new Set();
    for (const [r, c] of dig) {
        dug.add(r * n + c);
    }
    let ans = 0;
    for (const [r1, c1, r2, c2] of artifacts) {
        let ok = true;
        for (let r = r1; r <= r2 && ok; r++) {
            for (let c = c1; c <= c2 && ok; c++) {
                if (!dug.has(r * n + c)) ok = false;
            }
        }
        if (ok) ans++;
    }
    return ans;
};
